"""
MCP server for catfact.ninja.
Generated by MCP-Forge. Every tool was validated before packaging.

Settings (environment variables):
  CATFACT_BASE_URL         the API's base URL (default: https://catfact.ninja)
"""
import base64
import os
import re
from typing import Annotated, Any, Literal, Optional, Union
from urllib.parse import quote

import httpx
from pydantic import Field
from mcp.server.mcpserver import MCPServer
from mcp.server.mcpserver.exceptions import ToolError
from mcp.types import ToolAnnotations

server = MCPServer('catfact.ninja')

BASE_URL_ENV = 'CATFACT_BASE_URL'
BASE_URL = (os.environ.get('CATFACT_BASE_URL') or 'https://catfact.ninja').rstrip("/")

# How this API accepts credentials. Each value is read from an environment
# variable, so secrets never pass through the AI client as tool arguments.
AUTH = []


# A path placeholder: {petId}, or :petId (the style some prose docs use).
_PLACEHOLDER = re.compile(r"\{([^{}/]+)\}|(?<=/):([A-Za-z_]\w*)")


def _fill_path(path, values):
    """'/pet/{petId}' + {"petId": 5} -> '/pet/5'.

    Each value is URL-encoded as ONE path segment ('/' becomes %2F), and '',
    '.' and '..' are refused. Without this, a value such as '../user/admin'
    would turn the request into a call to a different endpoint than the tool's.
    """
    def fill(match):
        name = match.group(1) or match.group(2)
        if values.get(name) is None:
            raise ToolError(f"Missing a value for the path parameter '{name}'.")
        segment = str(values[name])
        if segment in ("", ".", ".."):
            raise ToolError(f"{segment!r} is not a valid value for the path parameter '{name}'.")
        return quote(segment, safe="")
    return _PLACEHOLDER.sub(fill, path)


def _request(method, path, *, path_params=None, params=None, json=None, data=None, headers=None):
    """Sends one request to the API. Every tool below calls this.

    - fills the path's placeholders from path_params, encoded (see _fill_path)
    - prefixes BASE_URL and adds the credentials configured in AUTH
    - leaves out query parameters whose value is None (not set by the AI)
    - raises ToolError for an HTTP error, naming the status code: MCP clients
      show a ToolError's message to the AI, while any other exception reaches
      it only as a generic "Error executing tool"
    """
    if not BASE_URL:
        raise ToolError(f"The API base URL is not set. Set the {BASE_URL_ENV} environment variable.")
    path = _fill_path(path, path_params or {})
    params = {key: value for key, value in (params or {}).items() if value is not None}
    headers = dict(headers or {})
    cookies = {}
    for entry in AUTH:
        if entry["type"] == "basic":
            username, password = os.environ.get(entry["env"]), os.environ.get(entry["env_password"])
            if username and password:
                token = base64.b64encode(f"{username}:{password}".encode()).decode()
                headers["Authorization"] = f"Basic {token}"
            continue
        value = os.environ.get(entry["env"])
        if not value:
            continue                              # not configured: send the request without it
        if entry["type"] == "bearer":
            headers["Authorization"] = f"Bearer {value}"
        elif entry["type"] == "header":
            headers[entry["name"]] = value
        elif entry["type"] == "query":
            params[entry["name"]] = value
        elif entry["type"] == "cookie":
            cookies[entry["name"]] = value

    try:
        response = httpx.request(method, BASE_URL + path, params=params, json=json, data=data,
                                 headers=headers, cookies=cookies, timeout=30, follow_redirects=True)
    except httpx.HTTPError as error:
        raise ToolError(f"{method} {path} could not reach the API: {error}") from error

    if response.is_error:
        raise ToolError(f"{method} {path} failed with HTTP {response.status_code}: {response.text[:1000]}")
    if not response.content:
        return {"status": response.status_code}
    if "json" in response.headers.get("content-type", ""):
        return response.json()
    return response.text


@server.tool(annotations=ToolAnnotations(read_only_hint=True, idempotent_hint=True, open_world_hint=True))
def get_fact() -> Union[dict, list, str]:
    """Returns a random cat fact."""
    return _request("GET", "/fact")


if __name__ == "__main__":
    server.run()
